(function(E){ const x = E["exam-07"] = E["exam-07"] || {units:{}}; (x.units = x.units || {})["x07-r2"] = {"id":"x07-r2","patterns":["RA-nature","GT2-policy","GT2-career","PARA-cause","PARA-rules"],"title":{"en":"Reading 2: Passage 2 / Section 2","tr":"Reading 2: Passage 2 / Section 2","fa":"Reading ۲: متن ۲ (Passage 2) / بخش ۲ (Section 2)"},"objective":{"en":"In this lesson you will learn to match headings to sections by their main idea, choose two correct statements from five, and complete sentences with one word from the passage.","tr":"Bu derste başlıkları bölümlerle ana fikirlerine göre eşleştirmeyi, beş ifadeden doğru ikisini seçmeyi ve cümleleri metinden tek kelimeyle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری عنوان‌ها را بر اساس ایده‌ی اصلی با بخش‌ها جور کنی، از پنج جمله دو جمله‌ی درست را انتخاب کنی و جمله‌ها را با یک کلمه از متن کامل کنی."},"objectiveGT":{"en":"In this lesson you will learn to decide TRUE, FALSE or NOT GIVEN about rules and prices, and to complete sentences about a job application with up to three words or a number.","tr":"Bu derste kurallar ve fiyatlar hakkında TRUE, FALSE ya da NOT GIVEN’a karar vermeyi ve bir iş başvurusuyla ilgili cümleleri en fazla üç kelime ya da bir sayıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری درباره‌ی قانون‌ها و قیمت‌ها بین TRUE، FALSE و NOT GIVEN تصمیم بگیری و جمله‌هایی درباره‌ی یک درخواست شغلی را با حداکثر سه کلمه یا یک عدد کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 2: headings for a report","tr":"Reading Passage 2: bir rapor için başlıklar","fa":"Reading Passage 2: عنوان‌گذاری یک گزارش"},"objective":{"en":"In this lesson you will learn to match headings to sections by their main idea, choose two correct statements from five, and complete sentences with one word from the passage.","tr":"Bu derste başlıkları bölümlerle ana fikirlerine göre eşleştirmeyi, beş ifadeden doğru ikisini seçmeyi ve cümleleri metinden tek kelimeyle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری عنوان‌ها را بر اساس ایده‌ی اصلی با بخش‌ها جور کنی، از پنج جمله دو جمله‌ی درست را انتخاب کنی و جمله‌ها را با یک کلمه از متن کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Headings","tr":"Başlıklar","fa":"عنوان‌ها"},"value":"i-viii"},{"label":{"en":"Sections","tr":"Bölüm","fa":"بخش"},"value":"A-F"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: seagrass meadows","tr":"Bu sınav: deniz çayırları","fa":"این آزمون: چمنزارهای زیر دریا"},"intro":{"en":"Nature and the environment are the most common Academic subjects. A report like this has one clear idea per section, which is what a list of headings tests: you need the main idea, not a detail.","tr":"Doğa ve çevre en sık çıkan Academic konularıdır. Böyle bir raporun her bölümünde tek bir net fikir vardır; başlık listesi bunu ölçer: ayrıntı değil, ana fikir gerekir.","fa":"طبیعت و محیط زیست رایج‌ترین موضوع‌های Academic هستند. گزارشی مثل این در هر بخش یک ایده‌ی روشن دارد و فهرست عنوان‌ها همین را می‌سنجد: ایده‌ی اصلی لازم است، نه جزئیات."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-r2-ctx","exam":true,"patterns":["RA-nature","PARA-cause"],"often":{"pattern":"RA-nature","n":37,"of":120,"label":{"en":"Comes up often in the real exam: 37 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 37’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۷ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"A report on a threatened habitat","tr":"Tehdit altındaki bir yaşam alanı üzerine rapor","fa":"گزارشی درباره‌ی یک زیستگاه در خطر"},"asks":{"en":"A report in six lettered sections on an underwater habitat: what it is, why it matters, how it was lost, today’s threats, how people are restoring it, and how it can be protected. You match each section to a heading.","tr":"Su altındaki bir yaşam alanı hakkında harflerle ayrılmış altı bölümlük bir rapor: ne olduğu, neden önemli olduğu, nasıl kaybedildiği, bugünkü tehditler, nasıl yeniden oluşturulduğu ve nasıl korunabileceği. Her bölümü bir başlıkla eşleştirirsin.","fa":"گزارشی در شش بخشِ حرف‌دار درباره‌ی یک زیستگاه زیر آب: چیست، چرا مهم است، چطور از دست رفت، خطرهای امروز، مردم چطور دوباره احیایش می‌کنند و چطور می‌شود از آن محافظت کرد. هر بخش را به یک عنوان وصل می‌کنی."},"fields":["What it is","Why it matters","Past losses","Threats today","Restoration","Protection"],"words":[{"a":"often mistaken for","b":"easy to assume it is","tr":"çoğu zaman ... sanılır","fa":"اغلب با ... اشتباه گرفته می‌شود"},{"a":"valuable","b":"important / worth a lot","tr":"değerli","fa":"باارزش"},{"a":"nursery","b":"a place where young animals grow","tr":"yavru büyütme alanı","fa":"پرورشگاه بچه‌ها"},{"a":"disappearing","b":"being lost / declining","tr":"yok oluyor","fa":"در حال از بین رفتن"},{"a":"long ago","b":"well before modern times","tr":"çok önce","fa":"خیلی وقت پیش"},{"a":"threat","b":"danger / problem","tr":"tehdit","fa":"تهدید"},{"a":"block the light","b":"cloud the water","tr":"ışığı engellemek","fa":"جلوی نور را گرفتن"},{"a":"restore","b":"bring back","tr":"eski hâline getirmek","fa":"احیا کردن"},{"a":"transplant","b":"move a living plant to a new place","tr":"nakletmek","fa":"جابه‌جا کاشتن"},{"a":"monitor","b":"watch and check regularly","tr":"izlemek","fa":"پایش کردن"},{"a":"reverse","b":"undo / turn back","tr":"tersine çevirmek","fa":"برگرداندن"}],"traps":[{"en":"A heading that matches one sentence: a heading must cover the whole section, not one detail in it.","tr":"Tek bir cümleye uyan başlık: başlık bölümün tamamını kapsamalı, içindeki tek bir ayrıntıyı değil.","fa":"عنوانی که با یک جمله جور است: عنوان باید کل بخش را پوشش بدهد، نه یک جزئیات را."},{"en":"Same words, wrong heading: a heading may repeat a word from a section (\"value\") but describe something the section never discusses.","tr":"Aynı kelimeler, yanlış başlık: bir başlık bölümdeki bir kelimeyi (\"value\") tekrarlayıp bölümün hiç ele almadığı bir şeyi anlatabilir.","fa":"کلمه‌ی یکسان، عنوان غلط: ممکن است عنوانی کلمه‌ای از بخش را تکرار کند («value») ولی چیزی را توصیف کند که بخش اصلاً درباره‌اش حرف نمی‌زند."},{"en":"Choose TWO: an option may be true in general but not stated in the passage. Choose only what the passage says.","tr":"İKİ seç: bir seçenek genel olarak doğru olabilir ama metinde söylenmemiş olabilir. Yalnızca metnin söylediğini seç.","fa":"دو تا انتخاب کن: ممکن است گزینه‌ای به‌طور کلی درست باشد اما در متن گفته نشده باشد. فقط چیزی را انتخاب کن که متن می‌گوید."}],"example":{"text":"Section: \"Bees pollinate a third of our crops. They also produce honey and wax, and a single hive can earn a farmer a small income. Without them, fruit harvests would collapse.\"","item":"Which heading fits? (i) Honey as a source of income  (ii) Why bees matter to farming","answer":"(ii)","why":{"en":"Honey is one detail; the section as a whole explains why bees matter to farming.","tr":"Bal tek bir ayrıntı; bölüm bütünüyle arıların tarım için neden önemli olduğunu anlatıyor.","fa":"عسل یک جزئیات است؛ کل بخش توضیح می‌دهد چرا زنبورها برای کشاورزی مهم‌اند."}}},{"id":"RA-nature-report","ctx":["RA-nature"],"title":{"en":"Reports on ecosystems and the environment","tr":"Ekosistemler ve çevre üzerine raporlar","fa":"گزارش درباره‌ی زیست‌بوم‌ها و محیط زیست"},"asks":{"en":"A report in lettered paragraphs about an ecosystem or an environmental problem: what it is, why it matters, what threatens it and what is being done. Headings name each paragraph’s main idea; matching information asks where one detail is.","tr":"Bir ekosistem ya da çevre sorunu hakkında harfli paragraflardan oluşan bir rapor: ne olduğu, neden önemli olduğu, onu neyin tehdit ettiği ve neler yapıldığı. Başlıklar her paragrafın ana fikrini adlandırır; bilgi eşleştirme tek bir ayrıntının nerede olduğunu sorar.","fa":"گزارشی با پاراگراف‌های حرف‌دار درباره‌ی یک زیست‌بوم یا یک مشکل محیط‌زیستی: چیست، چرا مهم است، چه چیزی تهدیدش می‌کند و چه کاری انجام می‌شود. عنوان‌ها ایده‌ی اصلی هر پاراگراف‌اند؛ جورکردن اطلاعات می‌پرسد یک نکته‌ی جزئی کجاست."},"fields":["The economic value of the forest","An unexpected benefit","Causes of decline","Early attempts at protection","A way of measuring change","Which paragraph mentions a comparison with another region?"],"words":[{"a":"a threat to","b":"puts at risk / endangers","tr":"... için tehdit","fa":"تهدیدی برای"},{"a":"causes","b":"the reasons / what led to","tr":"nedenler","fa":"علت‌ها"},{"a":"an unexpected benefit","b":"a surprising advantage","tr":"beklenmedik bir fayda","fa":"فایده‌ای غیرمنتظره"},{"a":"economic value","b":"worth money / income from","tr":"ekonomik değer","fa":"ارزش اقتصادی"},{"a":"early attempts","b":"the first efforts / initially tried","tr":"ilk girişimler","fa":"تلاش‌های اولیه"},{"a":"a new approach","b":"a different method / instead, now","tr":"yeni bir yaklaşım","fa":"رویکردی تازه"},{"a":"measuring","b":"monitoring / recording","tr":"ölçme","fa":"اندازه‌گیری"},{"a":"restore","b":"bring back / replant","tr":"eski haline getirmek","fa":"احیا کردن"},{"a":"long-term","b":"over decades / in the future","tr":"uzun vadeli","fa":"بلندمدت"},{"a":"local communities","b":"people living nearby","tr":"yerel halk","fa":"جوامع محلی"},{"a":"a comparison","b":"unlike / whereas in","tr":"bir karşılaştırma","fa":"یک مقایسه"},{"a":"consequences","b":"effects / results","tr":"sonuçlar","fa":"پیامدها"}],"traps":[{"en":"The detail trap: one heading matches a single detail of the paragraph, not its main idea.","tr":"Ayrıntı tuzağı: bir başlık paragrafın ana fikrine değil, tek bir ayrıntısına uyar.","fa":"دام جزئیات: یک عنوان با یک نکته‌ی جزئیِ پاراگراف جور است، نه با ایده‌ی اصلی‌اش."},{"en":"Matching information: the detail may sit in a paragraph whose main idea is something else.","tr":"Bilgi eşleştirme: ayrıntı, ana fikri başka bir şey olan bir paragrafta olabilir.","fa":"جورکردن اطلاعات: جزئیات ممکن است در پاراگرافی باشد که ایده‌ی اصلی‌اش چیز دیگری است."}],"example":{"text":"D  Restoring peat bogs was once thought to be simple: block the drains and wait for the water to return. Yet in many early projects the peat stayed dry for years, because the bogs had sunk below the level of the land around them.","item":"Choose the heading for paragraph D:  i  Why early restoration often failed   ii  The value of peat for farming   iii  How drains are built","answer":"i","why":{"en":"\"Once thought to be simple... yet... stayed dry\" = early attempts that failed. Drains are only a detail.","tr":"\"Bir zamanlar basit sanılıyordu... ama... kuru kaldı\" = başarısız ilk girişimler. Kanallar yalnızca bir ayrıntı.","fa":"«زمانی ساده تصور می‌شد... ولی... خشک ماند» = تلاش‌های اولیه‌ی ناموفق. زهکش‌ها فقط یک نکته‌ی جزئی‌اند."}},"track":"academic","general":true,"patterns":["RA-nature"],"often":{"pattern":"RA-nature","n":37,"of":120,"label":{"en":"Comes up often in the real exam: 37 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 37’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۷ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Headings, two pairs, then sentences","tr":"Başlıklar, iki çift, sonra cümleler","fa":"عنوان‌ها، دو جفت، بعد جمله‌ها"},"body":{"en":"Questions 14-19: choose the correct heading for each section from a list of eight; two headings are not used. Questions 20-21 and 22-23: choose TWO letters, A-E. Questions 24-26: complete sentences with ONE WORD ONLY from the passage.","tr":"Soru 14-19: her bölüm için sekiz başlıklık bir listeden doğru başlığı seç; iki başlık kullanılmaz. Soru 20-21 ve 22-23: A-E’den İKİ harf seç. Soru 24-26: cümleleri metinden ONE WORD ONLY ile tamamla.","fa":"سؤال‌های ۱۴ تا ۱۹: از فهرستی هشت‌تایی، عنوان درست هر بخش را انتخاب کن؛ دو عنوان استفاده نمی‌شوند. سؤال‌های ۲۰-۲۱ و ۲۲-۲۳: از A تا E دو حرف انتخاب کن. سؤال‌های ۲۴ تا ۲۶: جمله‌ها را با ONE WORD ONLY از متن کامل کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Main idea first","tr":"Önce ana fikir","fa":"اول ایده‌ی اصلی"},"steps":[{"en":"Read each section quickly and say its main idea to yourself in three or four words.","tr":"Her bölümü hızlıca oku ve ana fikrini üç dört kelimeyle kendine söyle.","fa":"هر بخش را سریع بخوان و ایده‌ی اصلی‌اش را در سه چهار کلمه برای خودت بگو."},{"en":"Then find the heading that means the same; ignore headings that match only one word or one sentence.","tr":"Sonra aynı anlama gelen başlığı bul; yalnızca bir kelimeye ya da bir cümleye uyan başlıkları göz ardı et.","fa":"بعد عنوانی را پیدا کن که همان معنی را دارد؛ عنوان‌هایی را که فقط با یک کلمه یا یک جمله جورند نادیده بگیر."},{"en":"Do the sections you are sure of first, then use the remaining headings for the harder ones.","tr":"Önce emin olduğun bölümleri yap, sonra kalan başlıkları daha zor olanlar için kullan.","fa":"اول بخش‌هایی را انجام بده که مطمئنی و بعد عنوان‌های باقی‌مانده را برای بخش‌های سخت‌تر به کار ببر."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Detail headings","tr":"Ayrıntı başlıkları","fa":"عنوان‌های جزئی"},"body":{"en":"Wrong headings are often true of one sentence in a section, or repeat a striking word from it. A section about the value of a habitat may mention money once, but a heading about money would describe only a detail.","tr":"Yanlış başlıklar çoğu zaman bir bölümdeki tek bir cümle için doğrudur ya da oradaki dikkat çekici bir kelimeyi tekrarlar. Bir yaşam alanının değeri hakkındaki bir bölüm paradan bir kez söz edebilir, ama parayla ilgili bir başlık yalnızca bir ayrıntıyı anlatır.","fa":"عنوان‌های غلط اغلب درباره‌ی یک جمله از بخش درست‌اند یا یک کلمه‌ی چشمگیر از آن را تکرار می‌کنند. بخشی درباره‌ی ارزش یک زیستگاه ممکن است یک بار از پول حرف بزند، اما عنوانی درباره‌ی پول فقط یک جزئیات را توصیف می‌کند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One heading, step by step","tr":"Bir başlık, adım adım","fa":"یک عنوان، قدم به قدم"},"instruction":"Choose the correct heading for the section.","text":"\"Wetlands were once drained for farming across Europe. Over three centuries, most of them disappeared, and many birds that depended on them became rare.\"","item":"(i) Birds that live in wetlands  (ii) The historical loss of wetlands  (iii) Modern farming methods","answer":"(ii)","walk":[{"en":"Main idea in your own words: \"wetlands lost over centuries\".","tr":"Kendi kelimelerinle ana fikir: \"yüzyıllar boyunca kaybolan sulak alanlar\".","fa":"ایده‌ی اصلی با کلمه‌های خودت: «تالاب‌هایی که در طول قرن‌ها از دست رفتند»."},{"en":"(i) is a detail in the last sentence; (iii) repeats \"farming\" but the section is not about methods.","tr":"(i) son cümledeki bir ayrıntı; (iii) \"farming\" kelimesini tekrarlıyor ama bölüm yöntemlerle ilgili değil.","fa":"(i) جزئیاتی در جمله‌ی آخر است؛ (iii) «farming» را تکرار می‌کند، اما بخش درباره‌ی روش‌ها نیست."},{"en":"(ii) matches the whole section.","tr":"(ii) bölümün tamamına uyuyor.","fa":"(ii) با کل بخش جور است."}]},"quick":{"prompt":"A section describes how a town raised money, hired builders and finally reopened its old theatre. Which heading fits best?","options":["Bringing a theatre back to life","The cost of building work","Finding good builders"],"correct":0,"why":{"en":"The whole section is about reopening the theatre; the other two describe parts of it.","tr":"Bölümün tamamı tiyatronun yeniden açılmasıyla ilgili; diğer ikisi bunun parçalarını anlatıyor.","fa":"کل بخش درباره‌ی بازگشایی دوباره‌ی تئاتر است؛ دو گزینه‌ی دیگر بخش‌هایی از آن را توصیف می‌کنند."}},"remember":{"en":"Name the main idea of each section first, then find the heading that matches all of it, not one sentence.","tr":"Önce her bölümün ana fikrini adlandır, sonra tek bir cümleye değil bölümün tamamına uyan başlığı bul.","fa":"اول ایده‌ی اصلی هر بخش را نام ببر و بعد عنوانی را پیدا کن که با کل آن جور است، نه با یک جمله."},"type":"explain","id":"c-x07-r2-e","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 2","title":{"en":"Meadows under the sea","tr":"Deniz altındaki çayırlar","fa":"چمنزارهای زیر دریا"},"timed":20,"ctx":["RA-nature"],"intro":"You should spend about 20 minutes on Questions 14-26, which are based on Reading Passage 2 below.","passage":"Meadows under the sea\n\nA  Swimmers in shallow, sheltered bays sometimes find themselves floating over what looks like a field of long green grass. It is easy to assume that this is seaweed, but it is something quite different. Seagrasses are true flowering plants, more closely related to lilies and grasses on land than to the algae that grow on rocks. They have roots, stems and leaves, and they even produce flowers and seeds, with their pollen carried from plant to plant by the water itself. Because they need sunlight, they grow only in clear, shallow water, usually less than ten metres deep. A single meadow can cover several square kilometres, and some are thought to be thousands of years old, spreading slowly outwards as new shoots grow from their underground stems.\n\nB  For a long time, these underwater meadows attracted little attention, but scientists now regard them as among the most valuable habitats on the planet. They act as nurseries for young fish, which shelter among the leaves until they are large enough to survive in open water, and they provide food for animals such as turtles and many kinds of shellfish. Their roots hold the sand and mud of the sea floor together, and the dense leaves reduce the force of waves before they reach the shore, which helps to protect coasts from erosion. Seagrass meadows also store large amounts of carbon in the sediment beneath them. Some researchers claim that, area for area, they lock away carbon faster than tropical forests, although estimates vary widely.\n\nC  Despite their importance, seagrass meadows have been disappearing for a long time. Some estimates suggest that around a third of the world's seagrass has been lost over the last century or so, and in some regions the figure is much higher. The losses began well before modern pollution. In the 1930s, a disease spread through the meadows of the North Atlantic and destroyed most of them within a few years, on both sides of the ocean. Many of these meadows never returned, and fishermen noticed the effects on their catches for decades afterwards. Scientists still do not fully understand why the disease was so destructive at that time, although some suggest that unusually warm water may have weakened the plants.\n\nD  Today the threats are different, but no less serious. The most widespread is pollution from the land. Fertilisers washed off farmland and waste from sewage works add nutrients to coastal water, which encourage the growth of algae. The algae cloud the water and cover the leaves, blocking the light the seagrass needs. Physical damage is another problem. Every time a boat drops its anchor in a meadow, the anchor and chain tear up plants, and the fixed moorings used in many harbours leave circular bare patches as their chains drag across the sea floor. Dredging for new ports and channels can destroy whole meadows at once, and rising sea temperatures add further stress, especially in shallow bays that heat up quickly in summer.\n\nE  Bringing seagrass back has proved difficult. Early restoration projects tried to move adult plants from healthy meadows to damaged ones, but most of the transplants died, and the method harmed the meadows they were taken from. More recent projects work with seeds instead. Volunteers collect flowering shoots by hand in late summer and keep them in large tanks of seawater until the seeds fall. The seeds are then placed in small bags made of hessian, a natural fabric that rots away, and the bags are lowered to the sea floor in carefully chosen places. Results vary from site to site, but some new meadows are now spreading on their own. The work is slow, however: a team of volunteers may spend a whole season planting an area no larger than a football pitch.\n\nF  Planting new meadows is expensive, so many conservationists argue that protecting existing ones should come first, and that this can often be done through quite simple changes. In some bays, no-anchor zones have been marked with buoys, and traditional moorings have been replaced with designs that float above the sea floor instead of dragging across it. Farmers are being encouraged to use less fertiliser near rivers. Meadows are also monitored more closely than before, by divers and by drones that photograph large areas from the air. None of this will reverse a century of loss quickly, but it gives the remaining meadows a far better chance of survival. Local fishing communities, who were once suspicious of the rules, have increasingly come to support them as fish numbers recover.","groups":[{"instruction":"Questions 14-19. Reading Passage 2 has six sections, A-F. Choose the correct heading for each section from the list of headings below. Write the correct number, i-viii, in boxes 14-19 on your answer sheet.","qtype":"headings","bank":["i Dangers facing the meadows today","ii A plant that is often mistaken for something else","iii Simple measures to protect what remains","iv The commercial value of seagrass products","v Why these underwater fields matter","vi Growing new meadows from seed","vii A decline that started long ago","viii A complete recovery in sight"],"questions":[{"n":14,"kind":"match","prompt":"Section A","correct":1,"evidence":"It is easy to assume that this is seaweed, but it is something quite different","why":{"en":"ii: the section explains that seagrass is not seaweed but a flowering plant.","tr":"ii: bölüm deniz çayırının yosun değil çiçekli bir bitki olduğunu açıklıyor.","fa":"ii: بخش توضیح می‌دهد علف دریایی جلبک نیست، بلکه گیاهی گل‌دار است."},"trap":["TR-detail"]},{"n":15,"kind":"match","prompt":"Section B","correct":4,"evidence":"scientists now regard them as among the most valuable habitats on the planet","why":{"en":"v: nursery for fish, food for animals, coastal protection, carbon. The whole section is about why the meadows matter.","tr":"v: balıklar için yavru alanı, hayvanlar için besin, kıyı koruması, karbon. Bölümün tamamı çayırların neden önemli olduğuyla ilgili.","fa":"v: پرورشگاه ماهی، غذای جانوران، حفاظت از ساحل، کربن. کل بخش درباره‌ی اهمیت چمنزارهاست."},"trap":["TR-samewords"]},{"n":16,"kind":"match","prompt":"Section C","correct":6,"evidence":"The losses began well before modern pollution","why":{"en":"vii: the losses \"began well before modern pollution\", with a disease in the 1930s.","tr":"vii: kayıplar \"modern kirlilikten çok önce\" 1930’lardaki bir hastalıkla başladı.","fa":"vii: از دست رفتن‌ها «خیلی قبل از آلودگی امروزی» با یک بیماری در دهه‌ی ۱۹۳۰ شروع شد."},"trap":["TR-detail"]},{"n":17,"kind":"match","prompt":"Section D","correct":0,"evidence":"Today the threats are different, but no less serious","why":{"en":"i: pollution, anchors, moorings, dredging and warming are today’s dangers.","tr":"i: kirlilik, çapalar, şamandıra zincirleri, tarama ve ısınma bugünün tehlikeleri.","fa":"i: آلودگی، لنگرها، زنجیرهای مهار، لایروبی و گرم شدن خطرهای امروزند."},"trap":["TR-detail"]},{"n":18,"kind":"match","prompt":"Section E","correct":5,"evidence":"More recent projects work with seeds instead","why":{"en":"vi: after transplants failed, projects now collect seeds, store them and plant them in bags.","tr":"vi: nakiller başarısız olunca projeler artık tohum toplayıp saklıyor ve torbalarla dikiyor.","fa":"vi: بعد از شکست جابه‌جا کاشتن، پروژه‌ها حالا بذر جمع می‌کنند، نگه می‌دارند و در کیسه می‌کارند."},"trap":["TR-detail"]},{"n":19,"kind":"match","prompt":"Section F","correct":2,"evidence":"this can often be done through quite simple changes","why":{"en":"iii: no-anchor zones, new moorings, less fertiliser and monitoring. viii is wrong: \"None of this will reverse a century of loss quickly\".","tr":"iii: çapa yasağı bölgeleri, yeni şamandıralar, daha az gübre ve izleme. viii yanlış: \"Bunların hiçbiri bir asırlık kaybı hızla geri çevirmeyecek\".","fa":"iii: منطقه‌های بدون لنگر، مهارهای تازه، کود کمتر و پایش. viii غلط است: «هیچ‌کدام از این‌ها خسارت یک قرن را سریع جبران نمی‌کند»."},"trap":["TR-detail","TR-samewords"]}]},{"instruction":"Questions 20-21. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":20,"n2":21,"kind":"mcq2","prompt":"Which TWO benefits of seagrass meadows are mentioned in the passage?","options":["A They provide food for some sea animals.","B They produce oil that can be used as fuel.","C They weaken the waves.","D They attract large numbers of tourists.","E They remove plastic from the water."],"correct":[0,2],"evidence":"the dense leaves reduce the force of waves before they reach the shore","trap":["TR-paraphrase"],"why":{"en":"A: they \"provide food for animals such as turtles\". C: \"the dense leaves reduce the force of waves\". Fuel, tourists and plastic are not mentioned.","tr":"A: \"kaplumbağalar gibi hayvanlara besin sağlıyorlar\". C: \"sık yapraklar dalgaların gücünü azaltıyor\". Yakıt, turistler ve plastikten söz edilmiyor.","fa":"A: «برای جانورانی مثل لاک‌پشت غذا فراهم می‌کنند». C: «برگ‌های انبوه از شدت موج‌ها کم می‌کنند». از سوخت، گردشگر و پلاستیک حرفی نیست."}}]},{"instruction":"Questions 22-23. Choose TWO letters, A-E.","qtype":"mcq2","questions":[{"n":22,"n2":23,"kind":"mcq2","prompt":"Which TWO present-day causes of seagrass loss does the writer mention?","options":["A fishing nets dragged along the sea floor","B nutrients washed off farmland","C oil spilled by ships","D anchors dropped by boats","E noise from busy harbours"],"correct":[1,3],"evidence":"Fertilisers washed off farmland and waste from sewage works add nutrients","trap":["TR-samewords"],"why":{"en":"B: fertilisers \"washed off farmland\" add nutrients. D: an anchor \"tears up plants\". Nets, oil and noise are not mentioned, although harbours are.","tr":"B: \"tarlalardan yıkanan\" gübreler besin ekliyor. D: çapa \"bitkileri söküyor\". Ağlar, petrol ve gürültüden söz edilmiyor; limanlardan söz ediliyor ama başka nedenle.","fa":"B: کودهایی که «از زمین‌های کشاورزی شسته می‌شوند» مواد مغذی اضافه می‌کنند. D: لنگر «گیاه‌ها را از جا می‌کند». از تور، نفت و سروصدا حرفی نیست؛ بندرها هست، ولی به دلیل دیگری."}}]},{"instruction":"Questions 24-26. Complete the sentences below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 24-26 on your answer sheet.","qtype":"sentence","questions":[{"n":24,"kind":"gap","prompt":"Early restoration projects tried to move adult ___ to damaged areas.","accept":["plants"],"limit":1,"evidence":"tried to move adult plants from healthy meadows","why":{"en":"\"Early restoration projects tried to move adult plants from healthy meadows to damaged ones.\" Plural.","tr":"\"İlk restorasyon projeleri yetişkin bitkileri sağlıklı çayırlardan hasarlı olanlara taşımaya çalıştı.\" Çoğul.","fa":"«پروژه‌های اولیه‌ی احیا سعی کردند گیاه‌های بالغ را از چمنزارهای سالم به آسیب‌دیده‌ها ببرند». جمع."},"trap":["TR-plural"]},{"n":25,"kind":"gap","prompt":"Seeds are put into small bags made of a natural fabric called ___.","accept":["hessian"],"limit":1,"evidence":"small bags made of hessian","why":{"en":"\"Small bags made of hessian, a natural fabric that rots away.\"","tr":"\"Çürüyen doğal bir kumaş olan çuval bezinden yapılmış küçük torbalar.\"","fa":"«کیسه‌های کوچکی از کرباس، پارچه‌ای طبیعی که می‌پوسد»."},"trap":["TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"As well as divers, ___ are used to photograph large areas of meadow.","accept":["drones"],"limit":1,"evidence":"by divers and by drones that photograph large areas from the air","why":{"en":"\"By divers and by drones that photograph large areas from the air.\" Plural.","tr":"\"Dalgıçlar ve geniş alanları havadan fotoğraflayan dronlar tarafından.\" Çoğul.","fa":"«با غواص‌ها و پهپادهایی که از هوا از مناطق بزرگ عکس می‌گیرند». جمع."},"trap":["TR-plural","TR-limit"]}]}],"id":"c-x07-r2-d","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Restoration projects aim to bring the meadows back.\" To restore something is to...","options":["study it","sell it","return it to its earlier condition"],"correct":2,"why":{"en":"Restore = bring back to a good or earlier state.","tr":"Restore = iyi ya da önceki durumuna getirmek.","fa":"restore یعنی برگرداندن به حالت خوب یا قبلی."}},{"tests":"paraphrase","point":3,"prompt":"A choose-TWO option says \"reduce the force of waves\". Which words in a passage mean the same?","options":["the waves are larger in winter","the waves are weaker by the time they reach the shore","the plants grow near the waves"],"correct":1,"why":{"en":"Weaker waves = reduced force.","tr":"Daha zayıf dalgalar = azalmış güç.","fa":"موج‌های ضعیف‌تر یعنی شدتِ کم‌شده."}},{"tests":"method","point":1,"prompt":"A list has eight headings and the passage has six sections. What do you know?","options":["two headings are not used","two sections share a heading","every heading is used"],"correct":0,"why":{"en":"Each section has one heading; two in the list are extra.","tr":"Her bölümün bir başlığı var; listede iki tane fazladan başlık var.","fa":"هر بخش یک عنوان دارد؛ دو عنوان فهرست اضافه‌اند."}},{"tests":"trap","point":2,"prompt":"A section on a river’s pollution mentions, in one sentence, that it is popular with anglers. Which heading is a trap?","options":["How the river became polluted","The causes of the river’s decline","A favourite place for fishing"],"correct":2,"why":{"en":"Fishing is one detail; the section is about pollution.","tr":"Balıkçılık tek bir ayrıntı; bölüm kirlilikle ilgili.","fa":"ماهیگیری یک جزئیات است؛ بخش درباره‌ی آلودگی است."}}],"id":"c-x07-r2-x","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"},"gt":{"explain":{"title":{"en":"GT Reading Section 2: rules and an application guide","tr":"GT Reading Section 2: kurallar ve bir başvuru rehberi","fa":"GT Reading Section 2: قانون‌ها و راهنمای درخواست"},"objective":{"en":"In this lesson you will learn to decide TRUE, FALSE or NOT GIVEN about rules and prices, and to complete sentences about a job application with up to three words or a number.","tr":"Bu derste kurallar ve fiyatlar hakkında TRUE, FALSE ya da NOT GIVEN’a karar vermeyi ve bir iş başvurusuyla ilgili cümleleri en fazla üç kelime ya da bir sayıyla tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری درباره‌ی قانون‌ها و قیمت‌ها بین TRUE، FALSE و NOT GIVEN تصمیم بگیری و جمله‌هایی درباره‌ی یک درخواست شغلی را با حداکثر سه کلمه یا یک عدد کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"3 words / number","tr":"3 kelime / sayı","fa":"۳ کلمه / عدد"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: scooter hire and a council job","tr":"Bu sınav: scooter kiralama ve bir belediye işi","fa":"این آزمون: کرایه‌ی اسکوتر و یک شغل در شهرداری"},"intro":{"en":"GT Section 2 is always about work and official information. Rules, policies and conditions are a frequent kind of text, and job applications are another. The questions follow each text in order.","tr":"GT Section 2 her zaman iş ve resmî bilgilerle ilgilidir. Kurallar, politikalar ve koşullar sık görülen bir metin türüdür; iş başvuruları da bir diğeri. Sorular her metni sırayla izler.","fa":"GT Section 2 همیشه درباره‌ی کار و اطلاعات رسمی است. قانون‌ها، سیاست‌ها و شرایط نوع رایجی از متن‌اند و درخواست شغل نوع دیگری. سؤال‌ها هر متن را به ترتیب دنبال می‌کنند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x07-r2gt-ctx","exam":true,"patterns":["GT2-policy","GT2-career","PARA-rules"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}},"title":{"en":"Hire rules and a job application guide","tr":"Kiralama kuralları ve bir iş başvuru rehberi","fa":"قانون‌های کرایه و راهنمای درخواست شغل"},"asks":{"en":"Text 1 is a set of rules and prices for a hire service: you decide TRUE, FALSE or NOT GIVEN. Text 2 explains how to apply for a job online: you complete sentences with up to three words or a number.","tr":"Metin 1 bir kiralama hizmetinin kuralları ve fiyatlarıdır: TRUE, FALSE ya da NOT GIVEN’a karar verirsin. Metin 2 çevrim içi iş başvurusunun nasıl yapılacağını anlatır: cümleleri en fazla üç kelime ya da bir sayıyla tamamlarsın.","fa":"متن ۱ قانون‌ها و قیمت‌های یک خدمت کرایه است: بین TRUE، FALSE و NOT GIVEN تصمیم می‌گیری. متن ۲ توضیح می‌دهد چطور آنلاین برای شغلی درخواست بدهی: جمله‌ها را با حداکثر سه کلمه یا یک عدد کامل می‌کنی."},"fields":["Who can use it","Prices","Safety rules","Parking","Getting started","Documents","Statement","After the closing date"],"words":[{"a":"under any circumstances","b":"never / in no situation","tr":"hiçbir koşulda","fa":"تحت هیچ شرایطی"},{"a":"recommended","b":"advised, but not required","tr":"tavsiye edilir","fa":"توصیه‌شده"},{"a":"a legal requirement","b":"the law says you must","tr":"yasal zorunluluk","fa":"الزام قانونی"},{"a":"not allowed","b":"is not permitted / may not","tr":"izin verilmez","fa":"مجاز نیست"},{"a":"unlimited","b":"as many as you like","tr":"sınırsız","fa":"نامحدود"},{"a":"a charge","b":"a fee added to your account","tr":"bir ücret","fa":"هزینه، جریمه"},{"a":"suspended","b":"stopped for a time","tr":"askıya alınmış","fa":"تعلیق‌شده"},{"a":"closing date","b":"the last day to apply","tr":"son başvuru tarihi","fa":"آخرین مهلت"},{"a":"saved automatically","b":"you don’t need to press save","tr":"otomatik kaydedilir","fa":"خودکار ذخیره می‌شود"},{"a":"no longer than","b":"a maximum of","tr":"en fazla","fa":"حداکثر"},{"a":"shortlisted","b":"chosen for the next stage","tr":"kısa listeye alınmış","fa":"در فهرست نهایی"}],"traps":[{"en":"Recommended is not required: \"advised, but not compulsory\" makes a \"must\" statement FALSE.","tr":"Tavsiye edilen zorunlu değildir: \"tavsiye edilir ama zorunlu değildir\", \"zorunda\" diyen bir ifadeyi FALSE yapar.","fa":"توصیه‌شده یعنی اجباری نیست: «توصیه می‌شود، ولی اجباری نیست» جمله‌ای با «باید» را FALSE می‌کند."},{"en":"NO MORE THAN THREE WORDS AND/OR A NUMBER: \"your bank details\" is three words; \"a copy of your bank details\" is too many.","tr":"NO MORE THAN THREE WORDS AND/OR A NUMBER: \"your bank details\" üç kelime; \"a copy of your bank details\" fazla.","fa":"NO MORE THAN THREE WORDS AND/OR A NUMBER: «your bank details» سه کلمه است؛ «a copy of your bank details» زیادی است."}],"example":{"text":"\"Lockers can be used free of charge, but you must bring your own padlock.\"","item":"Statement: Padlocks are provided for the lockers.","answer":"FALSE","why":{"en":"\"You must bring your own padlock\" contradicts \"padlocks are provided\".","tr":"\"Kendi asma kilidini getirmelisin\", \"asma kilitler sağlanır\" ile çelişiyor.","fa":"«باید قفل خودت را بیاوری» با «قفل داده می‌شود» تناقض دارد."}}},{"id":"GT2-policy","ctx":["GT2-policy"],"title":{"en":"Workplace policies and conditions","tr":"İş yeri politikaları ve çalışma koşulları","fa":"سیاست‌ها و شرایط محیط کار"},"asks":{"en":"A page from a staff handbook: parking, dress code, leave, absence, benefits or the complaints procedure. Questions test what staff must do, by when, and who they tell.","tr":"Bir personel el kitabından bir sayfa: otopark, kıyafet kuralı, izin, devamsızlık, yan haklar ya da şikâyet prosedürü. Sorular personelin ne yapması gerektiğini, ne zamana kadar ve kime haber vereceğini sınar.","fa":"صفحه‌ای از راهنمای کارکنان: پارکینگ، قانون پوشش، مرخصی، غیبت، مزایا یا روند رسیدگی به شکایت. سؤال‌ها می‌سنجند کارکنان چه باید بکنند، تا کی و به چه کسی خبر بدهند."},"fields":["Staff must inform their ___ before 9 a.m. if they are ill.","Holiday requests need ___ weeks’ notice.","Parking permits are issued by ___.","Jeans may be worn on ___."],"words":[{"a":"entitled to","b":"have the right to","tr":"... hakkı olmak","fa":"حق داشتن"},{"a":"annual leave","b":"holiday","tr":"yıllık izin","fa":"مرخصی سالانه"},{"a":"notice","b":"warning in advance","tr":"önceden haber","fa":"اطلاع قبلی"},{"a":"sick leave","b":"time off when you are ill","tr":"hastalık izni","fa":"مرخصی استعلاجی"},{"a":"permit","b":"an official permission card","tr":"izin kartı","fa":"مجوز"},{"a":"dress code","b":"rules about clothes","tr":"kıyafet kuralları","fa":"قانون پوشش"},{"a":"casual","b":"informal / relaxed","tr":"rahat, gündelik","fa":"غیررسمی"},{"a":"grievance","b":"a formal complaint","tr":"resmî şikâyet","fa":"شکایت رسمی"},{"a":"approve","b":"agree to / sign off","tr":"onaylamak","fa":"تأیید کردن"},{"a":"allowance","b":"money paid for something","tr":"ödenek","fa":"کمک‌هزینه"},{"a":"probation","b":"a trial period","tr":"deneme süresi","fa":"دوره‌ی آزمایشی"},{"a":"in writing","b":"by email or letter","tr":"yazılı olarak","fa":"به‌صورت کتبی"}],"traps":[{"en":"Who to tell: \"your line manager\" and \"HR\" are often named for different steps.","tr":"Kime haber verilir: \"bağlı olduğun yönetici\" ve \"İK\" çoğu zaman farklı adımlar için geçer.","fa":"به چه کسی خبر بدهی: «مدیر مستقیم» و «منابع انسانی» اغلب برای مرحله‌های مختلف نام برده می‌شوند."},{"en":"Periods: \"two weeks’ notice\" and \"within two weeks\" mean different things.","tr":"Süreler: \"iki hafta önceden haber\" ile \"iki hafta içinde\" farklı şeylerdir.","fa":"مدت‌ها: «دو هفته اطلاع قبلی» با «ظرف دو هفته» فرق دارد."}],"example":{"text":"If you cannot come to work because of illness, phone your line manager before 9 a.m. on the first day. HR only needs to be told if the absence lasts more than five working days.","item":"Staff who are ill must first contact their ___.   (NO MORE THAN TWO WORDS)","answer":"line manager","why":{"en":"The line manager is told first; HR only after five working days.","tr":"Önce bağlı olunan yöneticiye haber verilir; İK’ya ancak beş iş gününden sonra.","fa":"اول به مدیر مستقیم خبر می‌دهی؛ به منابع انسانی فقط بعد از پنج روز کاری."}},"track":"gt","general":true,"patterns":["GT2-policy"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}}},{"id":"GT2-career","ctx":["GT2-career"],"title":{"en":"Job and career guides","tr":"İş ve kariyer rehberleri","fa":"راهنمای کار و مسیر شغلی"},"asks":{"en":"Guides for job seekers and employees: CVs, interviews, promotion, resigning, freelance work, apprenticeships. Sentence and note completion test the advice.","tr":"İş arayanlar ve çalışanlar için rehberler: özgeçmiş, mülakat, terfi, istifa, serbest çalışma, çıraklık. Cümle ve not tamamlama tavsiyeleri sınar.","fa":"راهنما برای کارجوها و کارمندها: رزومه، مصاحبه، ترفیع، استعفا، کار آزاد، کارآموزی حرفه‌ای. کامل کردن جمله و یادداشت توصیه‌ها را می‌سنجد."},"fields":["Keep your CV to ___ pages.","Research the company before the ___.","Give your employer written ___ when you resign.","Freelancers must keep records for ___."],"words":[{"a":"CV","b":"career summary / résumé","tr":"özgeçmiş","fa":"رزومه"},{"a":"applicant","b":"candidate / person applying","tr":"başvuran","fa":"متقاضی"},{"a":"vacancy","b":"an open job","tr":"açık pozisyon","fa":"موقعیت شغلی خالی"},{"a":"interview","b":"meeting with the employer","tr":"mülakat","fa":"مصاحبه"},{"a":"resign","b":"leave your job / hand in your notice","tr":"istifa etmek","fa":"استعفا دادن"},{"a":"notice period","b":"time between resigning and leaving","tr":"ihbar süresi","fa":"مدت اطلاع قبلی"},{"a":"promotion","b":"moving up to a higher job","tr":"terfi","fa":"ترفیع"},{"a":"freelance","b":"self-employed / working for yourself","tr":"serbest","fa":"آزادکار"},{"a":"apprenticeship","b":"training while you work","tr":"çıraklık","fa":"کارآموزی حرفه‌ای"},{"a":"references","b":"people who will recommend you","tr":"referanslar","fa":"معرف‌ها"},{"a":"salary","b":"pay / earnings","tr":"maaş","fa":"حقوق"},{"a":"recent","b":"latest / most up to date","tr":"en son","fa":"جدیدترین"}],"traps":[{"en":"Advice for different stages: \"before the interview\" and \"after the interview\" are different paragraphs.","tr":"Farklı aşamalar için tavsiyeler: \"mülakattan önce\" ve \"mülakattan sonra\" farklı paragraflardadır.","fa":"توصیه برای مرحله‌های مختلف: «قبل از مصاحبه» و «بعد از مصاحبه» در پاراگراف‌های جدا هستند."},{"en":"The gap needs a word from the text, even if a synonym feels more natural.","tr":"Boşluk metinden bir kelime ister; eş anlamlısı daha doğal gelse bile.","fa":"جای خالی کلمه‌ای از متن را می‌خواهد، حتی اگر مترادفش طبیعی‌تر به نظر برسد."}],"example":{"text":"Most employers spend less than a minute on each CV, so keep yours to two pages and put your most recent job first.","item":"Sentence: Put your most ___ job first.   (ONE WORD ONLY)","answer":"recent","why":{"en":"\"Put your most recent job first.\" Copy recent; do not change it to \"latest\".","tr":"\"En son işini en başa koy.\" recent kelimesini kopyala; \"latest\" diye değiştirme.","fa":"«جدیدترین شغلت را اول بنویس». کلمه‌ی recent را کپی کن؛ به latest تغییرش نده."}},"track":"gt","general":true,"patterns":["GT2-career"],"often":{"pattern":"GT2-career","n":18,"of":55,"label":{"en":"Comes up often in the real exam: 18 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۵۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Statements, then sentences","tr":"Önce ifadeler, sonra cümleler","fa":"اول جمله‌های درست/غلط، بعد جمله‌های ناقص"},"body":{"en":"Questions 15-21: TRUE, FALSE or NOT GIVEN about the first text. Questions 22-27: complete sentences about the second text with NO MORE THAN THREE WORDS AND/OR A NUMBER from the text.","tr":"Soru 15-21: ilk metin hakkında TRUE, FALSE ya da NOT GIVEN. Soru 22-27: ikinci metinle ilgili cümleleri metinden NO MORE THAN THREE WORDS AND/OR A NUMBER ile tamamla.","fa":"سؤال‌های ۱۵ تا ۲۱: TRUE، FALSE یا NOT GIVEN درباره‌ی متن اول. سؤال‌های ۲۲ تا ۲۷: جمله‌هایی درباره‌ی متن دوم را با NO MORE THAN THREE WORDS AND/OR A NUMBER از متن کامل کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Rule words and word counts","tr":"Kural kelimeleri ve kelime sayısı","fa":"کلمه‌های قانون و شمارش کلمه"},"steps":[{"en":"For each statement, find the rule and check its strength: must, may, recommended, never, only.","tr":"Her ifade için kuralı bul ve gücüne bak: must, may, recommended, never, only.","fa":"برای هر جمله، قانون را پیدا کن و شدتش را بسنج: must، may، recommended، never، only."},{"en":"If the text does not mention the point at all, choose NOT GIVEN.","tr":"Metin o noktadan hiç söz etmiyorsa NOT GIVEN’ı seç.","fa":"اگر متن اصلاً به آن نکته اشاره نمی‌کند، NOT GIVEN را انتخاب کن."},{"en":"For sentences, find the heading, copy the words exactly and count them: three at most, and a number counts as one.","tr":"Cümleler için başlığı bul, kelimeleri aynen kopyala ve say: en fazla üç; bir sayı tek sayılır.","fa":"برای جمله‌ها عنوان را پیدا کن، کلمه‌ها را دقیقاً کپی کن و بشمار: حداکثر سه تا؛ یک عدد یکی حساب می‌شود."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Strong and weak rules","tr":"Güçlü ve zayıf kurallar","fa":"قانون‌های سخت و نرم"},"body":{"en":"Rules come in different strengths. \"Must\" and \"not allowed\" are rules; \"recommended\" and \"advised\" are advice; \"may lead to\" is a possibility. A statement that turns advice into a rule, or a possibility into a certainty, is FALSE.","tr":"Kuralların gücü farklıdır. \"Must\" ve \"not allowed\" kuraldır; \"recommended\" ve \"advised\" tavsiyedir; \"may lead to\" bir olasılıktır. Tavsiyeyi kurala ya da olasılığı kesinliğe çeviren bir ifade FALSE olur.","fa":"قانون‌ها شدت‌های متفاوتی دارند. «must» و «not allowed» قانون‌اند؛ «recommended» و «advised» توصیه‌اند؛ «may lead to» یک احتمال است. جمله‌ای که توصیه را قانون کند یا احتمال را قطعی، FALSE است."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One sentence, step by step","tr":"Bir cümle, adım adım","fa":"یک جمله، قدم به قدم"},"instruction":"Complete the sentence. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the text.","text":"\"Interviews usually last about forty-five minutes and include a short presentation.\"","item":"Candidates should expect to give a ___ at the interview.","answer":"short presentation","walk":[{"en":"The gap follows \"a\", so it needs a noun phrase.","tr":"Boşluk \"a\"dan sonra geliyor, yani bir isim öbeği gerekiyor.","fa":"جای خالی بعد از «a» است، پس یک گروه اسمی می‌خواهد."},{"en":"\"include a short presentation\" = should expect to give a presentation.","tr":"\"Kısa bir sunum içerir\" = bir sunum yapmayı beklemeli.","fa":"«شامل یک ارائه‌ی کوتاه است» یعنی باید انتظار ارائه دادن را داشته باشد."},{"en":"\"short presentation\" is two words: inside the limit.","tr":"\"short presentation\" iki kelime: sınırın içinde.","fa":"«short presentation» دو کلمه است: در محدوده‌ی مجاز."}]},"quick":{"prompt":"Text: \"Gloves are recommended when handling the plants.\" Statement: \"Staff must wear gloves when handling the plants.\" TRUE, FALSE or NOT GIVEN?","options":["TRUE","FALSE","NOT GIVEN"],"correct":1,"why":{"en":"\"Recommended\" is advice; \"must\" makes it a rule, which contradicts the text.","tr":"\"Recommended\" tavsiyedir; \"must\" onu kurala çeviriyor, bu da metinle çelişiyor.","fa":"«recommended» توصیه است؛ «must» آن را قانون می‌کند که با متن تناقض دارد."}},"remember":{"en":"Check how strong each rule is, choose NOT GIVEN when the point is missing, and count every word you copy.","tr":"Her kuralın ne kadar güçlü olduğuna bak, nokta eksikse NOT GIVEN’ı seç ve kopyaladığın her kelimeyi say.","fa":"ببین هر قانون چقدر سخت است، اگر نکته‌ای نیامده NOT GIVEN را انتخاب کن و هر کلمه‌ای را که کپی می‌کنی بشمار."},"type":"explain","id":"c-x07-r2-e-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 2","title":{"en":"Scooter hire and a council job","tr":"Scooter kiralama ve bir belediye işi","fa":"کرایه‌ی اسکوتر و شغلی در شهرداری"},"timed":20,"ctx":["GT2-policy","GT2-career"],"texts":[{"title":"Zipway e-scooter hire: rules and prices","kind":"hire rules and prices","body":"Zipway e-scooters are available across the city centre 24 hours a day. Before your first ride, please read these rules carefully. By unlocking a scooter, you agree to follow them.\n\nWho can ride\nYou must be 18 or over to hire a scooter, and you must have a full or provisional driving licence, which you upload through the app when you register. Riders under 18 cannot hire a scooter under any circumstances, even with a parent's permission.\n\nPrices\nEach ride costs £1 to unlock, plus 20p for every minute you ride. If you plan to use scooters a lot in one day, a day pass costs £12 and gives you unlimited rides for 24 hours. Monthly passes are also available through the app.\n\nSafety\nHelmets are strongly recommended, although they are not a legal requirement. Scooters may only be ridden on roads and in cycle lanes, never on pavements. Only one person may ride a scooter at a time; carrying a passenger, of any age, is not allowed. Scooters are limited to 15 mph, and they slow down automatically to 8 mph in pedestrian areas such as the market square.\n\nParking\nAt the end of your ride, you must leave the scooter in one of the marked parking bays shown in the app. If you leave it anywhere else, a £15 charge will be added to your account, because our staff will have to collect it.\n\nDamage and faults\nCheck the scooter before you ride. If you notice any damage or a fault, report it in the app and do not use the scooter. You will not be charged for a fault that you report before your ride.\n\nYour account\nRepeated breaking of these rules, such as riding on pavements, may lead to your account being suspended. If you have any questions, our customer team can be contacted through the app between 7 am and 10 pm."},{"title":"Applying for a job with Ashbury Council: a guide to our online system","kind":"application guide","body":"All vacancies at Ashbury Council are advertised on our jobs website, and all applications must be made online. This guide explains how to complete the process. If you do not have access to a computer, you can use the free computers at any of our libraries, where staff will be happy to help.\n\nGetting started\nBefore you begin, you will need to create an online account on the jobs website, using your email address and a password. You can then search for vacancies and save any that interest you.\n\nCompleting the form\nThe application form has five sections. You do not need to complete it in one go: your application is saved automatically every five minutes, and you can log out and return to it at any time before the closing date. Make sure you submit the form before midnight on the closing date, as late applications cannot be accepted for any reason.\n\nSupporting documents\nFor most posts, you will be asked to upload copies of your qualification certificates. These must be in PDF format. Please do not send original documents by post, as we cannot return them.\n\nSupporting statement\nThis is the most important part of your application. Explain how your skills and experience match the requirements listed in the job description, giving examples where possible. Examples from voluntary work, education or family life are just as valid as examples from paid employment. Your statement should be no longer than 1,000 words.\n\nInterviews\nIf you need any adjustments to be made for an interview, such as wheelchair access or extra time for a written test, please contact the recruitment team as soon as possible.\n\nAfter the closing date\nApplications are reviewed by the manager of the department. Shortlisted candidates will be contacted within three weeks of the closing date. If you have not heard from us by then, your application has not been successful on this occasion."}],"groups":[{"text":0,"instruction":"Questions 15-21. Do the following statements agree with the information given in the text? In boxes 15-21 on your answer sheet, write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":15,"kind":"tfng","prompt":"Riders under 18 can hire a scooter if a parent agrees.","correct":"FALSE","evidence":"Riders under 18 cannot hire a scooter under any circumstances","why":{"en":"\"Cannot hire a scooter under any circumstances, even with a parent’s permission.\"","tr":"\"Hiçbir koşulda scooter kiralayamaz, ebeveyn izniyle bile.\"","fa":"«تحت هیچ شرایطی نمی‌توانند اسکوتر کرایه کنند، حتی با اجازه‌ی پدر و مادر»."},"trap":["TR-NGvsF"]},{"n":16,"kind":"tfng","prompt":"A provisional driving licence is accepted.","correct":"TRUE","evidence":"you must have a full or provisional driving licence","why":{"en":"\"A full or provisional driving licence\" is required, so a provisional one is accepted.","tr":"\"Tam ya da geçici bir ehliyet\" gerekiyor; yani geçici ehliyet kabul ediliyor.","fa":"«گواهینامه‌ی کامل یا موقت» لازم است، پس گواهینامه‌ی موقت پذیرفته می‌شود."},"trap":["TR-paraphrase"]},{"n":17,"kind":"tfng","prompt":"Riders are legally required to wear a helmet.","correct":"FALSE","evidence":"they are not a legal requirement","why":{"en":"Helmets are \"strongly recommended\" but \"not a legal requirement\".","tr":"Kasklar \"şiddetle tavsiye ediliyor\" ama \"yasal zorunluluk değil\".","fa":"کلاه ایمنی «به‌شدت توصیه می‌شود»، اما «الزام قانونی نیست»."},"trap":["TR-hedge"]},{"n":18,"kind":"tfng","prompt":"Students can buy the day pass at a reduced price.","correct":"NOT GIVEN","evidence":"a day pass costs £12","why":{"en":"The text gives the price of the day pass but says nothing about discounts for students.","tr":"Metin günlük kartın fiyatını veriyor ama öğrenci indiriminden söz etmiyor.","fa":"متن قیمت بلیت روزانه را می‌گوید، اما درباره‌ی تخفیف دانشجویی چیزی نمی‌گوید."},"trap":["TR-NGvsF"]},{"n":19,"kind":"tfng","prompt":"Two adults may share one scooter.","correct":"FALSE","evidence":"carrying a passenger, of any age, is not allowed","why":{"en":"\"Only one person may ride a scooter at a time; carrying a passenger, of any age, is not allowed.\"","tr":"\"Bir scooter’a aynı anda yalnızca bir kişi binebilir; her yaştan yolcu taşımak yasak.\"","fa":"«هر بار فقط یک نفر می‌تواند سوار شود؛ بردن مسافر، در هر سنی، مجاز نیست»."},"trap":["TR-NGvsF"]},{"n":20,"kind":"tfng","prompt":"Users pay extra if they leave a scooter outside a marked bay.","correct":"TRUE","evidence":"a £15 charge will be added to your account","why":{"en":"\"If you leave it anywhere else, a £15 charge will be added to your account.\"","tr":"\"Başka bir yere bırakırsan hesabına 15 £ ücret eklenir.\"","fa":"«اگر جای دیگری بگذاری، ۱۵ پوند به حسابت اضافه می‌شود»."},"trap":["TR-paraphrase"]},{"n":21,"kind":"tfng","prompt":"Scooters travel more slowly in wet weather.","correct":"NOT GIVEN","evidence":"they slow down automatically to 8 mph in pedestrian areas","why":{"en":"The scooters slow down in pedestrian areas; nothing is said about the weather.","tr":"Scooter’lar yaya bölgelerinde yavaşlıyor; hava durumundan hiç söz edilmiyor.","fa":"اسکوترها در منطقه‌های پیاده کند می‌شوند؛ از وضع هوا حرفی نیست."},"trap":["TR-NGvsF","TR-samewords"]}]},{"text":1,"instruction":"Questions 22-27. Complete the sentences below. Choose NO MORE THAN THREE WORDS AND/OR A NUMBER from the text for each answer. Write your answers in boxes 22-27 on your answer sheet.","qtype":"sentence","questions":[{"n":22,"kind":"gap","prompt":"Before searching for vacancies, applicants must create an ___ on the jobs website.","accept":["online account"],"limit":3,"evidence":"you will need to create an online account on the jobs website","why":{"en":"\"You will need to create an online account\": two words.","tr":"\"Çevrim içi bir hesap oluşturman gerekecek\": iki kelime.","fa":"«باید یک حساب آنلاین بسازی»: دو کلمه."},"trap":["TR-limit","TR-paraphrase"]},{"n":23,"kind":"gap","prompt":"The application form is saved automatically every ___.","accept":["five minutes","5 minutes"],"limit":3,"evidence":"your application is saved automatically every five minutes","why":{"en":"\"Saved automatically every five minutes.\"","tr":"\"Her beş dakikada bir otomatik kaydediliyor.\"","fa":"«هر پنج دقیقه خودکار ذخیره می‌شود»."},"trap":["TR-limit","TR-paraphrase"]},{"n":24,"kind":"gap","prompt":"For most jobs, applicants upload copies of their ___.","accept":["qualification certificates"],"limit":3,"evidence":"upload copies of your qualification certificates","why":{"en":"\"Copies of your qualification certificates\": \"copies of\" is printed, so two words.","tr":"\"Yeterlilik belgelerinin kopyaları\": \"copies of\" yazılı, iki kelime.","fa":"«کپی مدرک‌های تحصیلی‌ات»: «copies of» چاپ شده، پس دو کلمه."},"trap":["TR-limit","TR-paraphrase"]},{"n":25,"kind":"gap","prompt":"The supporting statement must not be longer than ___.","accept":["1,000 words","1000 words"],"limit":3,"evidence":"Your statement should be no longer than 1,000 words","why":{"en":"\"No longer than 1,000 words\" = must not be longer than.","tr":"\"1.000 kelimeden uzun olmamalı\".","fa":"«بیشتر از ۱۰۰۰ کلمه نباشد»."},"trap":["TR-limit","TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"Candidates who need changes made for an interview should contact the ___.","accept":["recruitment team"],"limit":3,"evidence":"please contact the recruitment team as soon as possible","why":{"en":"\"Please contact the recruitment team\": \"the\" is printed.","tr":"\"Lütfen işe alım ekibiyle iletişime geçin\": \"the\" yazılı.","fa":"«لطفاً با تیم استخدام تماس بگیر»: «the» چاپ شده."},"trap":["TR-limit","TR-paraphrase"]},{"n":27,"kind":"gap","prompt":"Shortlisted applicants hear from the council within ___ of the closing date.","accept":["three weeks","3 weeks"],"limit":3,"evidence":"will be contacted within three weeks of the closing date","why":{"en":"\"Contacted within three weeks of the closing date.\"","tr":"\"Son başvuru tarihinden itibaren üç hafta içinde iletişime geçilir.\"","fa":"«ظرف سه هفته بعد از آخرین مهلت با آن‌ها تماس گرفته می‌شود»."},"trap":["TR-limit","TR-paraphrase"]}]}],"id":"c-x07-r2-d-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Shortlisted candidates will be contacted.\" Shortlisted means...","options":["chosen for the next stage","turned down","late with their application"],"correct":0,"why":{"en":"A shortlist is a small group chosen from all the applicants.","tr":"Kısa liste, tüm adaylar arasından seçilen küçük bir gruptur.","fa":"فهرست کوتاه گروه کوچکی است که از بین همه‌ی متقاضی‌ها انتخاب می‌شود."}},{"tests":"paraphrase","point":3,"prompt":"A statement says \"must\". Which words in a rules text make it FALSE?","options":["is required","is compulsory","is strongly advised"],"correct":2,"why":{"en":"Advice is not an obligation; required and compulsory mean must.","tr":"Tavsiye zorunluluk değildir; required ve compulsory \"must\" demektir.","fa":"توصیه الزام نیست؛ required و compulsory یعنی must."}},{"tests":"method","point":2,"prompt":"Sentence: \"Members must first choose a ___\" (NO MORE THAN THREE WORDS AND/OR A NUMBER). The text says \"choose a security password of at least eight characters\". Which answer is right?","options":["security password of eight characters","security password","password of at least eight characters"],"correct":1,"why":{"en":"Two words complete the sentence; the other answers are over the limit.","tr":"İki kelime cümleyi tamamlıyor; diğer cevaplar sınırı aşıyor.","fa":"دو کلمه جمله را کامل می‌کند؛ جواب‌های دیگر از سقف بیشترند."}},{"tests":"trap","point":3,"prompt":"Text: \"Breaking the rules may lead to a fine.\" Statement: \"Anyone who breaks the rules will be fined.\"","options":["FALSE","TRUE","NOT GIVEN"],"correct":0,"why":{"en":"\"May lead to\" is a possibility; \"will be\" makes it certain, which contradicts the text.","tr":"\"Yol açabilir\" bir olasılık; \"will be\" onu kesinleştiriyor, bu da metinle çelişiyor.","fa":"«ممکن است منجر شود» یک احتمال است؛ «will be» آن را قطعی می‌کند که با متن تناقض دارد."}}],"id":"c-x07-r2-x-gt","course":"ielts-exams","exam":"exam-07","unit":"x07-r2"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
